let maxVowels = function(s, k)
{
    let maxVowel = 0;
    let currVowel = 0;
    let n = s.length;

    for (let i=0; i<k; i++)
    {
        if (s[i]=='a' || s[i]=='e' || s[i]=='i' || s[i]=='o' || s[i]=='u')
        {
            maxVowel += 1;
        }
    }
    currVowel = maxVowel;

    for (let i=0; i<n-k; i++)
    {
        if (s[i]=='a' || s[i]=='e' || s[i]=='i' || s[i]=='o' || s[i]=='u')
        {
            currVowel = currVowel - 1;
        }

        if (s[i+k]=='a' || s[i+k]=='e' || s[i+k]=='i' || s[i+k]=='o' || s[i+k]=='u')
        {
            currVowel = currVowel + 1;
        }
        if (currVowel > maxVowel)
        {
            maxVowel = currVowel;
        }
    }
    return maxVowel;
}

// let s = "leetcode";
let s = "";
let k = 3945;
let output = maxVowels(s,k);
console.log(output);